#include <stdio.h>

int process_length(int32_t len) {
    uint32_t max_len = 1000;
    if (len > max_len) {
        return -1;
    }
    return 0;
}

int main(void) {
    int32_t test = -1;
    if (process_length(test) == -1) {
        printf("Length too large\n");
    } else {
        printf("Length OK\n");
    }
    return 0;
}
